#' Standard Error Of Mean
#'
#' 
#' @param data .
#' @param x .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$sem} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
SEM <- function(
    data,
    x) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("SEM requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL))


    options <- SEMOptions$new(
        x = x)

    analysis <- SEMClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

